<script setup lang="ts">
import { computed, ref } from 'vue'
import type { RepoRank } from '@/api/discover'
import { repoGrowth } from './contract'
import DiscoverGlyph from './DiscoverGlyph.vue'
type Repo=RepoRank&{icon?:string;language_color?:string;tint?:string;spark?:number[]}
const props=withDefaults(defineProps<{repo:Repo;compact?:boolean;baseline?:boolean}>(),{compact:false,baseline:false})
const key='xiaoban.web.repo-bookmarks'
function readSaved(){try{const parsed=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(parsed)?parsed.filter((v:unknown):v is string=>typeof v==='string').slice(0,500):[]}catch{return []}}
const saved=ref(readSaved().includes(props.repo.full_name)),saveError=ref('')
function toggle(){const next=!saved.value;try{const old=readSaved();localStorage.setItem(key,JSON.stringify(next?[props.repo.full_name,...old.filter(v=>v!==props.repo.full_name)].slice(0,500):old.filter(v=>v!==props.repo.full_name)));saved.value=next;saveError.value=''}catch{saveError.value='浏览器无法保存收藏'}}
const color=computed(()=>/^#[\da-f]{6}$/i.test(props.repo.language_color||'')?props.repo.language_color:'var(--ink-3)')
const spark=computed(()=>props.repo.star_gain!=null?(props.repo.spark||[]).filter(Number.isFinite):[])
const bars=computed(()=>{const max=Math.max(1,...spark.value);return spark.value.map(v=>Math.max(2,v/max*24))})
const href=computed(()=>`https://github.com/${props.repo.full_name.split('/').map(encodeURIComponent).join('/')}`)
const glyph=computed(()=>({term:'terminal',code:'code',doc:'doc',mic:'mic',bolt:'bolt'} as Record<string,string>)[props.repo.icon||''])
</script>
<template><article class="repo-card" :class="{compact}"><div class="repo-main"><span class="rank" :class="{top:repo.rank<=3}">{{ String(repo.rank).padStart(2,'0') }}</span><a :href="href" class="repo-link" target="_blank" rel="noopener noreferrer"><span class="repo-icon"><DiscoverGlyph v-if="glyph" :name="glyph" :size="20"/><span v-else>{{ repo.full_name.split('/').at(-1)?.slice(0,1).toUpperCase() }}</span></span><h3>{{ repo.full_name }}</h3><DiscoverGlyph class="external" name="external" :size="14"/></a><button v-if="!compact" type="button" class="save" :class="{saved}" :aria-label="`${saved?'取消本机收藏':'收藏到当前浏览器'} ${repo.full_name}`" :aria-pressed="saved" @click="toggle"><DiscoverGlyph name="bookmark" :size="18"/></button></div><div class="repo-meta"><span v-if="repo.language" class="language"><i :style="{background:color}"/>{{ repo.language }}</span><span class="stars"><DiscoverGlyph name="star" :size="14"/>{{ repo.star_total.toLocaleString('zh-CN') }}</span><span v-if="!baseline&&repo.star_gain!=null" class="growth">{{ repoGrowth(repo.star_gain) }} Star</span><span v-if="bars.length>=2" class="spark" aria-hidden="true"><i v-for="(bar,index) in bars" :key="index" :style="{height:`${bar}px`}"/></span></div><p v-if="repo.suspected_growth" class="note">增长异常 · 待复核</p><p v-else-if="!compact&&!baseline&&repo.star_gain!=null&&repo.observed_days!=null&&!repo.complete" class="note">实际观测 {{ repo.observed_days }} 天</p><p v-if="saveError" class="note" role="status">{{ saveError }}</p></article></template>
<style scoped>
.repo-card{min-width:0;background:var(--surface);padding:14px;border-radius:16px}.repo-main{display:flex;align-items:center;gap:8px}.rank{width:22px;flex:none;font-size:14px;font-variant-numeric:tabular-nums;color:var(--ink-3)}.rank.top{color:var(--brand)}.repo-link{display:flex;align-items:center;gap:10px;flex:1;min-width:0;min-height:44px}.repo-icon{display:grid;place-items:center;flex:none;width:32px;height:32px;border-radius:8px;background:var(--surface-2);color:var(--ink-2);font-size:16px;font-weight:600}h3{margin:0;flex:1;min-width:0;font-size:15px;font-weight:600;line-height:1.5;overflow-wrap:anywhere}.external{color:var(--ink-3);flex:none;opacity:.65}.save{display:grid;place-items:center;width:44px;height:44px;flex:none;background:none;border:0;border-radius:50%;color:var(--ink-3);cursor:pointer}.save.saved{color:var(--brand);background:color-mix(in srgb,var(--brand) 8%,var(--surface))}.repo-meta{display:flex;align-items:center;flex-wrap:wrap;gap:8px 12px;padding-top:8px;color:var(--ink-3);font-size:12px}.language,.stars{display:inline-flex;align-items:center;gap:5px}.language i{width:6px;height:6px;border-radius:50%}.growth{margin-left:auto;color:var(--ink-2);font-variant-numeric:tabular-nums}.spark{height:24px;display:inline-flex;align-items:flex-end;gap:2px}.spark i{width:3px;border-radius:2px;background:var(--ink-3);opacity:.35}.note{font-size:12px;line-height:1.6;margin:8px 0 0;color:var(--ink-3)}.compact{padding:12px 0;border-radius:0}.compact+.compact{border-top:.5px solid var(--line)}.compact .repo-icon{width:32px;height:32px}.compact .repo-meta{padding-left:30px}.compact h3{font-size:14px}.compact .repo-link{min-height:36px}
@media(min-width:768px){.repo-card{padding:16px}.compact{padding:12px 0}}
</style>
